void min_max(const int data[], int size, int *min, int *max)
{
    *min = data[0];
    *max = data[0];
    for (int i = 1; i < size; i++) {
        if (data[i] < *min) *min = data[i];
        if (data[i] > *max) *max = data[i];
    }
}

